-- Seed script generated by seeds/seedDatabase.js

BEGIN;

-- Create tables if they do not exist
CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT UNIQUE,
  avatar_url TEXT,
  total_km INTEGER DEFAULT 0,
  avg_altitude INTEGER DEFAULT 0,
  avg_time_hr NUMERIC DEFAULT 0,
  role TEXT DEFAULT 'user'
);

CREATE TABLE IF NOT EXISTS trails (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  location TEXT,
  difficulty TEXT,
  length_km NUMERIC,
  duration_hr NUMERIC,
  rating NUMERIC,
  description TEXT,
  image_url TEXT,
  lat NUMERIC,
  lng NUMERIC
);

CREATE TABLE IF NOT EXISTS reviews (
  id SERIAL PRIMARY KEY,
  trail_id INTEGER REFERENCES trails(id) ON DELETE CASCADE,
  user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  rating INTEGER,
  comment TEXT
);

CREATE TABLE IF NOT EXISTS trail_categories (
  id SERIAL PRIMARY KEY,
  name TEXT UNIQUE NOT NULL
);

CREATE TABLE IF NOT EXISTS trail_category_map (
  trail_id INTEGER REFERENCES trails(id) ON DELETE CASCADE,
  category_id INTEGER REFERENCES trail_categories(id) ON DELETE CASCADE,
  PRIMARY KEY(trail_id, category_id)
);




-- Map trails to categories
WITH tc AS (SELECT id, name FROM trail_categories)
SELECT 1;


COMMIT;

-- Verification queries
SELECT COUNT(*) AS trails_count FROM trails;
SELECT COUNT(*) AS users_count FROM users;
SELECT COUNT(*) AS reviews_count FROM reviews;
