INSERT INTO trail_category_map (trail_id, category_id) SELECT t.id, tc.id FROM trails t, trail_categories tc WHERE tc.name = 'Beginner' AND (t.id % 3) = 0;
INSERT INTO trail_category_map (trail_id, category_id) SELECT t.id, tc.id FROM trails t, trail_categories tc WHERE tc.name = 'Intermediate' AND (t.id % 3) = 1;
INSERT INTO trail_category_map (trail_id, category_id) SELECT t.id, tc.id FROM trails t, trail_categories tc WHERE tc.name = 'Expert' AND (t.id % 3) = 2;
